class Solution { public int[] minInterval(int[][] intervals,int[] queries){Arrays.sort(intervals,Comparator.comparingInt(a->a[0]));Integer[] order=new Integer[queries.length];for(int i=0;i<order.length;i++)order[i]=i;Arrays.sort(order,Comparator.comparingInt(i->queries[i]));PriorityQueue<int[]> heap=new PriorityQueue<>(Comparator.comparingInt(a->a[0]));int[] answer=new int[queries.length];Arrays.fill(answer,-1);int next=0;for(int index:order){int value=queries[index];while(next<intervals.length&&intervals[next][0]<=value){heap.offer(new int[]{intervals[next][1]-intervals[next][0]+1,intervals[next][1]});next++;}while(!heap.isEmpty()&&heap.peek()[1]<value)heap.poll();if(!heap.isEmpty())answer[index]=heap.peek()[0];}return answer;} }
